import json

with open('data/baihua-tasks/t1251.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

translations = data['translations']
n = len(translations)
modern = [""] * n

# 段0
modern[0] = "【多聞天王說法】那時多聞寶藏吽迦陀王對一切眾生說：「我守護佛法僧三寶，庇佑三界一切眾生。又為南閻浮提五濁惡世中的出家比丘、比丘尼，以及在家優婆塞、優婆夷等作守護。這裡有大陀羅尼法，還有能縛一切惡咒的法門，名為根本普通真言、如意寶珠真言、大禁縛大祕密真言、成萬事真言、大禁縛吽迦陀野相應忿怒咒語。【义解】本段為全經開端，由本尊多聞天王（即穢跡金剛吽迦陀野）開宗明義，宣說本法的護持宗旨，列舉五類核心真言，標明此法是護持三寶、利益五濁惡世眾生的密教儀軌。"
# 段1
modern[1] = "【持法滅罪生福】如果有善男子、善女人，乃至畜生等眾生，聽聞這些真言的名號以及我的名號，歸依這個法門，誦持真言與密印法門，生生世世都不會遭受一切災難病患，不會投生到邊地惡國，不會墮入十八地獄受苦，不會遭遇無量怨敵，常常能遇到善友善知識，修行佛道，獲得無量福德，自在修證阿耨多羅三藐三菩提。【义解】本段宣說聽聞、歸依、修持本法的廣大功德：消災免難、不墮惡趣、常遇善知識、精進佛道、最終成就無上菩提，彰顯此法的殊勝加持力。"
# 段2
modern[2] = "【普禮淨業印明】因此多聞王為一切眾生宣說普禮法。這個印相是金剛合掌，普禮真言說：「唵迦陀（一）　吽那迪（二合）尼（二）　娑婆訶」「接著是自身懺悔印：左右手結內縛拳，左右手的風指（食指）各豎立，左手風指貼在右手風指根部，右手風指放在左手風指下方根部，從上向下七遍左右放開，就能淨化三業。【义解】本段進入具體儀軌教授：先講普禮印（金剛合掌）與對應真言，再講懺悔淨三業印的結法與操作次數，屬於修法前行的禮敬、懺悔環節，用來清淨身口意三業。"
# 段3
modern[3] = "【淨三業印真言】淨三業真言說：「唵曩謨三滿多󰂛馱喃（二）　唵（三）　嚩多麼馱多曩（四）　伽溜𭤶野吽（五）（引）」「依靠這個印與真言，身口意三業所有的不淨都能完全消除，證得諸佛智慧海，也就是禪波羅蜜的境界。「接著結聖者吽迦陀野入三昧耶護身印，就能具足精進波羅蜜。【义解】本段講授淨三業印對應的真言，以及持誦此印明的功德：淨除三業罪障，得諸佛智慧，相應禪波羅蜜；隨後引出下一步的三昧耶護身印，對應精進波羅蜜。"
# 段4
modern[4] = "【三昧耶護身印相】這個印相是二手合掌，二水指（無名指）一起伸入掌內交叉，二火指（中指）指尖相柱，二風指（食指）和二火指的背面相靠成鉤形不分開，二地指（小指）並立，二空指（大拇指）伸入掌內並立。用這個印做辟除結界，印在五個地方：額頭、右肩、左肩、心、喉嚨，然後將印從頂上散開當心，觀想這個印是大火聚的形相，觀想羅字種子字。【义解】本段詳細講解吽迦陀野三昧耶護身印的結法、印五處的順序位置、以及觀想要點（觀大火聚、羅字），這是結界護身、驅除魔障的關鍵印契，屬於修法前行的防護環節。"
# 段5
modern[5] = "【護身結界真言】真言說：「曩謨三滿多冒馱南（一）　唵（二）　救娑蘭（二合）（二一）　唵（四）吠室羅麼那野（五）　唵（六）　俱（七）　𮥟（八）　毘曳（二合）地梨（二合）智（九）　吽支智盧（十）　娑婆賀（引）」「依靠這個密印法門，身口意三業所有的一切惡業重罪，乃至誹謗佛法僧、誹謗大乘經典、與一闡提同等的重罪，依靠這個印明都能完全消除。【义解】本段是三昧耶護身印對應的真言，以及持誦此印明的滅罪功德：能滅除毀謗三寶、毀謗大乘等極重惡業，是修法前清淨罪障、獲得本尊守護的核心步驟。"
# 段6
modern[6] = "【本尊根本大印】另外一切臭穢污濁的場所，依靠這個明法，所有不淨都能消滅，獲得清淨事業的瑜伽相應。就觀想這是吽迦陀野一面十手大密藏智大生印。如果這個印明結一次被護自身，就生生世世無量生不會墮入惡處，常常值遇諸佛法僧，聽聞佛法得到究竟果位。「接著應當結成萬事相應心印。【义解】本段補充護身印的特殊功德：能清淨一切穢惡不淨之地，令行者瑜伽相應；同時點明此印就是本尊穢跡金剛一面十手根本印，結一次即得廣大善根，隨後過渡到成萬事心印。"
# 段7
modern[7] = "【成萬事隨心印】二手（闕文），二大指（空指）伸入掌內，二風指（食指）做成寶珠的形狀，二空指並列橫臥，風指指尖相對。用這個印印五處，觀想頂上的吽字。隨心真言說：「唵支智（一）　盧（二）　娑婆賀（引）」「依靠這個真言印的力量，一切毘那夜迦等不祥惡神都不敢靠近。這就是一切如來的大智印。【义解】本段講授成萬事相應心印（隨心印）的結法、觀想要點（頂上現吽字）、對應真言，以及護持功德：遣除毘那夜迦等障礙，是一切如來所說的大智印，可成辦一切世間出世間事業。"
# 段8
modern[8] = "【三部三昧耶分別】這三個法就是這個法門的三部三昧耶：最初的自身淨真言就是法藏印；其次的火光印明，是諸天的密語藏，對應僧伽（蓮華部）；第三個隨心印語，就是一切佛藏（佛部）。這樣行者的身體就成為金剛身。念加持香水的真言說：「吽尾訖梨跢（一）　都那伽多僧尼吽（二合）【义解】本段總結前三印（淨三業印、火光護身印、隨心印）分別對應法、僧、佛三寶，也就是密教三部三昧耶，令行者身成金剛堅固之身；接著引出加持香水的真言，進入灑淨道場的環節。"
# 段9
modern[9] = "【加持香水散水真言】「（三）　度縛颯颯（四）　吽（五）　吽發吒（半音）」「取金剛杵加持後散灑淨水的真言說：「吽（一）　吽（二）　吽（三）　吽（四）」「接著應當誦大禁縛請聖降壇、堅縛不祥的偈語：「唵縛日羅（二合）（一）　揭羅陀那多𮗇耶夜（二）【义解】本段接續上文，圓滿加持香水真言，以及用金剛杵散灑淨水的四吽真言，隨後引出大禁縛結界請聖的偈咒，用來淨化道場、堅固結界，防止惡神障礙修法。"
# 段10
modern[10] = "【禁縛諸惡結界偈】「　南無毘娑麼尼（三）　修羅尾普（四）　麼陀羅耶（五）（引）　社羅（六）（同）麼賀薩埵耶（七）（引）　唬侶（入引）阿羅（入引）達麼尼（八）（引）　唵（九）（引入）　麼尼麼尼（引）㗭哆（引）入入入（入引）【义解】本段是大禁縛結界咒的中間部分，為梵文密咒，原字照錄不翻，用來禁縛道場內外一切惡鬼神、惡障礙，令其不能動作，守護道場清淨。"
# 段11
modern[11] = "【結界禁咒圓滿】「婆耶（十）（引）　𭝲多羅（入）（十一）（引）　麼賀（十二）　迦羅耶（十三）（引）　㗭陀（入）吽陀羅耶（十四）（入）唵治瑟吒婆耶（十五）　唵（十六）（引）　拔悉多（引）唬陀耶（十七）（引入）　曩謨（十八）【义解】本段繼續記錄大禁縛結界咒的後半部分，密咒原字保留，功能是進一步堅固結界，降伏一切魔障，令道場成為清淨聖地。"
# 段12
modern[12] = "【請聖降臨道場】「（引）」這片土地、這個州國、這個寺院、所有比丘、比丘尼、在家信眾等，弟子某甲至心勸請三世十方一切諸佛菩薩、諸明王、聲聞緣覺諸賢聖眾，以及上居天、地居天等護法、護世四王、十二天等，四方四角的諸神王、一切鬼王、諸夜叉大將眷屬，不捨本誓，來入道場，證明知見我所修的一切法事。【义解】本段是結界之後的請聖文，行者至心奉請十方三世一切三寶聖眾、護法善神降臨道場，作為修法的證明，守護加持行者。"
# 段13
modern[13] = "【禮請四方神王】因此我比丘、比丘尼、僧俗弟子等至心請命頂禮：曩謨東方各領四悉多唬多耶，曩謨八大曼陀羅界會聖眾，曩謨東方各領八萬四千鬼神王；南方各領八萬四千鬼神王，西方各領八萬四千鬼神王，北方各領八萬四千鬼神王，中央各領八萬四千鬼神王，大神各領八萬四千鬼神王眷屬等。【义解】本段依次頂禮東、南、西、北、中五方各領八萬四千眷屬的鬼神王，以及八大曼荼羅聖眾，是請聖環節中召請八方護法神王的內容。"
# 段14
modern[14] = "【禮請五方道斷神】曩謨東方單陀利道斷，南方單多梨道斷，西方單埵梨道斷，北方單荼里道斷，中央單多里道斷，大神單陀利道斷。曩謨東方迦羅迦羅，南方迦羅迦羅，西方迦羅迦羅，北方迦羅迦羅，中央迦羅迦羅，大神迦羅迦羅。【义解】本段頂禮五方的道斷神（單陀利類）與迦羅迦羅神王，這些是守護各方道路、斷除障難的護法神，屬於結界守護的善神眷屬。"
# 段15
modern[15] = "【禮請各天護法眾】曩謨東方那吒鬼神王，南方那吒鬼神王，西方那吒鬼神王，北方那吒鬼神王，中央那吒鬼神王，大神那吒鬼神王。十方各立，四方也是一樣。曩謨護法聖眾摩醯首羅，知足天二十八宿主護，毘沙門天王、四大天王，眾天，三十三天、四分天、知足天、樂變化天、他化自在天、梵眾天、梵善益天、大梵天、小光天、無量光天、極光天、小淨天、遍淨天、無量淨天、自在天、無憂天、無煩天、無熱天、福生天、廣果天、善見天、善現天、色究竟天、無邊空處天、無邊色處天、無所有處天、非想非非想處天。【义解】本段依次頂禮五方那吒神王，以及三界二十八天、四禪天、四空天等一切天眾，廣泛召請天上護法善神降臨道場。"
# 段16
modern[16] = "【禮請龍天護法眾】二十八天主護毘沙門天王，三界覆護者堅牢地主，正了知大將，迦利底女五百眷屬，金剛密跡寶賢大將、僧真儞耶藥叉大將。南無三十三天，禪那莫鬼及緊那羅王、阿耨達龍王、沙竭羅王、阿修羅王、迦樓羅王、大辨天神及大功德天。【义解】本段頂禮二十八部眾的主護毘沙門天王、堅牢地神、諸藥叉大將，以及龍王、阿修羅、迦樓羅、大辯才天、大功德天等八部眾護法，進一步擴大請聖的範圍。"
# 段17
modern[17] = "【禮請大力鬼神眾】如是以上首領的諸天神等，釋提桓因及日月天、閻摩羅王、風水諸神、違馱天神，及毘紐天、大辨天神，及自在天大神等大力勇猛大鬼神王，那羅延天等、諸鬼神等。散指為首百千鬼神、摩尼拔陀大鬼神王、富那拔陀，及金剛羅迦毘羅王、阿羅婆帝、賓頭盧伽黃頭天神，一一諸神各有五百眷屬鬼神。【义解】本段頂禮帝釋、日月、閻摩、風水、毘紐、那羅延等天界大神，以及散指、摩尼拔陀、富那拔陀等大鬼神王與其眷屬，召請一切大力護法降臨。"
# 段18
modern[18] = "【禮請其餘神眾】質多斯那阿修羅王，及乾闥婆、那羅羅闍根那娑金色髮神王、半祈鬼神，及半支羅主、雨大神、大飲食神、摩訶伽吒車鉢羅婆有大威德婆那利神、曇摩跢羅摩竭娑羅針髮鬼神、繡梨密多勒那翅者摩訶婆及軍陀遮鐱摩舍帝。【义解】本段列舉阿修羅王、乾闥婆、各類特色神王、鬼神的名號，繼續召請六道中的護法善神，令其蒞臨道場守護。"
# 段19
modern[19] = "【禮請童子眷屬眾】復有大神奢羅密帝、醯摩拔陀、薩多踦梨、南無娜那多陀耶、曩謨日單捶拔遊羅㗭哆婆那、唵拔（長引）曩無金剛童子、一字頂龍王，梨車毘童子及五億八千眷屬，他們的名號是：師子光童子、師子惠童子、授法授童子、因陀羅童子、大光童子、大猛童子、佛護童子、法護童子、僧護童子、金剛護童子、虛空護童子、虛空吼童子、寶藏童子、吉祥妙藏童子。【义解】本段頂禮其餘大神、金剛童子、龍王以及十四位童子眷屬，這些都是本尊的隨從護法，召請他們降臨護持修法。"
# 段20
modern[20] = "【堅縛一切惡眾】南無十羅剎女等一切使者大將等，至心堅縛天神、堅縛地神、堅縛四方四角神等。堅縛明神等，堅縛大神、堅縛小神、堅縛惡神、堅縛一切惡靈、堅縛一切怨敵惡人等。堅縛惡人令其決定被調伏，堅縛堅縛，唵拔逝羅堅縛婆四保侶保盧娑耶娑婆訶（長引浪音出引）【义解】本段是堅縛咒的內容，在請聖之後，用真言堅固縛住一切惡神、惡靈、惡人、怨敵，令其不能作障，守護道場安寧。"
# 段21
modern[21] = "【結界印與功德】。「印相是結金剛拳，分別放在兩膝上，睜開忿怒眼觀視四方。如果有人誦持這個偈咒，這個人就能消滅百八煩惱以及六十二見，獲得無量福德自在。為什麼呢？這個真言是諸佛所稱歎的，從這個真言中流出我的心法，這個大陀羅尼偈能調伏一切惡事。誦這個偈的時候，應當觀想一切大惡物毘那夜迦、各大惡鬼神王、各類外道、天地四方魔鬼眾、國內大小神等，全都被禁縛，攝入行者的心內。【义解】本段講堅縛咒的印相（金剛拳置膝、忿怒視四方）與功德：消滅煩惱邪見，得大福德，能調伏一切惡鬼神、外道魔鬼，將其攝入行者心中，不令作障。"
# 段22
modern[22] = "【誦咒觀字灑淨】如果一遍誦咒時聲音拉長，用忿怒降伏的音聲，誦完就念吽字、羅字、欠字。「灑淨真言說：「唵第誐增伽（二合引）野吽（一）　索縛伽（引佉）」「如果想要修這個法，首先應當選擇在佛前、塔前、僧房，或者河邊林下的蘭若處，還有自己心中喜愛沒有障難的地方，這是最上等的悉地成就處所。【义解】本段講誦結界咒的音聲要點、誦後觀種子字（吽、羅、欠），接著給出灑淨真言，並說明修法道場的選擇標準：清淨無難、三寶所在或寂靜蘭若處。"
# 段23
modern[23] = "【擇地作壇法式】修這個真言法的行者，應當先清理出地裡的髑髏、死骨、瓦石等惡臭污穢之物。然後行者到清淨的地方，取乾淨的土作壇曼陀羅，然後再修真言法。取土的時候，如果是佛部法就用真言加持，然後取土作壇：息災法（扇底迦）的壇是圓形，增益法（補瑟微迦）的壇是四角形，降伏法（阿毘遮嚕迦）的壇是八角形，各個壇大小作八肘，也可以作五肘、三肘大小。【义解】本段講道場的清理：除去穢物，取淨土築壇；並分別說明息災、增益、降伏三種法對應的壇身形狀與尺寸，是築造曼荼羅壇場的基本規範。"
# 段24
modern[24] = "【加持地界真言】加持作壇地的真言說：「唵難馱難馱（一）　娜智娜智難達婆里薩嚩賀（引）」「如果有受持真言法的人，作壇的時候先誦這個真言一百零八遍，加持地界，地下的一切蟲蟻之類都會轉移避開到其他地方，這片地方就得到清淨。選好作壇的地方之後，就造作大法的八大曼陀羅，它們的名字是：一因曼陀羅界、二法入曼陀羅界、三入相曼陀羅界、四入藏曼陀羅界、五妙藏曼陀羅界、六證入曼陀羅界、七圓法曼陀羅界、八相應曼陀羅界。【义解】本段講加持地界的真言與用法：誦108遍加持令蟲蟻遠離、地界清淨；隨後列出本法核心的八大曼荼羅的名稱，是曼荼羅築造的總綱。"
# 段25
modern[25] = "【八大曼荼羅釋名】這就叫八大曼陀羅界，也就是八大曼陀羅。一一解釋它們的名義：因曼荼羅，就是種子曼陀羅。法入曼陀羅，就是大壇，有三種護摩爐壇；入相曼陀羅，就是行者做護摩的時候，心中觀想本尊的體相，睜開忿怒眼觀想佛位尊形，也就是觀念曼陀羅；入藏曼陀羅，就是吉祥天等眷屬部類的排列位次，也就是吉祥天女王和九位天女眷屬的壇位。【义解】本段開始逐一解釋八大曼荼羅的含義：先釋因曼荼羅（種子壇）、法入曼荼羅（護摩主壇）、入相曼荼羅（觀想本尊壇）、入藏曼荼羅（吉祥天女眷屬壇）。"
# 段26
modern[26] = "【曼荼羅師資標準】妙藏世界，就是種子曼陀羅。諸位聖尊都從自己的本位來集會，安住本來的座位，成就所修的法門。行者如果對這個壇界的相狀明明了了，才有資格稱為阿闍梨；對於這個壇界不了了的人，不能稱為阿闍梨。這個界就是成就世界，這個界名叫傳法輪壇。證入界，就是都鉢等諸夜叉大將軍的座位所在。【义解】本段接續解釋妙藏曼荼羅，說明通達八大曼荼羅位佈是成為阿闍梨的必備條件；同時解釋證入曼荼羅是諸夜叉大將的座位，也就是本尊攝受護法眷屬的壇位。"
# 段27
modern[27] = "【諸尊壇位觀想】圓法世界，就是毘沙門王以及二位忿怒相應的八牙天等聖尊。相應世界，就是大日如來、釋迦牟尼佛、四千不動尊、觀世音菩薩、彌勒菩薩等聖尊。這就叫八大曼陀羅。行者首先應當觀想八大世界，先把它們的相狀如法觀清楚。造作這樣的曼陀羅之後，接著用心觀想圓法世界，首先中間的主尊毘沙門天，身上披著七寶金剛莊嚴的鎧甲，左手捧寶塔、右手執三叉戟，腳下踏著三隻夜叉鬼。【义解】本段解釋圓法曼荼羅（毘沙門與八牙天）、相應曼荼羅（佛菩薩聖眾），隨後開始教導圓法曼荼羅中主尊毘沙門天王的觀想要點：身相、持物、坐騎踏鬼的形態。"
# 段28
modern[28] = "【主尊眷屬觀想】中間的主尊座下是地天，又名歡喜天。左右是使者天女，左邊名叫尼藍婆女天、右邊名叫毘藍婆神王。三隻鬼的面相形體都要觀想端正。左右的女天，也要觀想她們相好具足。座下還有五位太子，都現將軍身、披著鎧甲，手中各持弓箭。還有五位行道天女，也披著鎧甲，現端正女相，手中持鐮刀。【义解】本段接續圓法曼荼羅的觀想：觀想主尊毘沙門座下的地天、左右使者天女、踏的三夜叉、五位太子、五位行道天女的形相、服飾、持物，令壇場聖眾觀想清晰。"
# 段29
modern[29] = "【其餘聖眾觀想】又有其他天眾，也披著甲冑，現忿怒面，手持刀鐮，各自坐在石座上。這就叫十人大將眾。吉祥天現圓滿好相，各種衣服莊嚴無與倫比。天女左手持青蓮華、右手結施無畏印，頭上以五寶莊嚴。眼睛望著毘沙門王現慈愛相，面容細膩姣好、白裡透紅，坐在蓮葉座上。【义解】本段繼續圓法曼荼羅的觀想：十人大將的忿怒相，以及主尊眷屬吉祥天的相好、持物、印相、坐姿、面相特徵，令觀想細節圓滿。"
# 段30
modern[30] = "【八牙天眾觀想】九位使者天女，也現殊勝好相，世間無有能比。吉祥天眷屬，各手持寶刀，也有持鉾的，也有持鏡的，每三個人持一種器物，各坐在蓮葉座上。還有八牙王相，背對外站立，面色赤紅，衣服黑色，每面有三隻眼睛，有的半面三目、有的半面二目。上方的牙指著自己，下方長長的白牙從袖子脅下露出，每顆牙都對正胸口。【义解】本段觀想吉祥天座下的九位天女眷屬的持物與座位，以及南方八牙忿怒天王的獨特相好：身色、面色、衣色、三目、長牙的特徵，是忿怒尊觀想的要點。"

